"""Tool-use contracts, surface links, data locations and business roles of ciso-assistant-mcp.

Each contract names one resource family and its operations in the order a caller uses
them: list, read, create, update, delete, then the resource actions. The SDK serves
this declaration as the connector's surface ontology and checks it against the served
tools, prompts and skills.
"""

# ruff: noqa: E501
